// Stateless Custom Deleter (Optimization via EBO)
// Deleter type: closure type (usually zero-size)
auto resource_deleter = [](int* p) {
    if (p) std::cout << "Deleting"; delete p;
};

using OptimizedPtr = 
    std::unique_ptr<int, decltype(resource_deleter)>;

// If resource_deleter is stateless (no captures):
// sizeof(OptimizedPtr) == sizeof(int*) 
// (Zero size overhead via Empty Base Optimization)

OptimizedPtr p(new int(42), resource_deleter);

// Compiler knows the deleter type at compile time,
// enabling potential inlining of the deletion call.
